#!/usr/bin/env python3
"""Quick debug: render the poster and check rendered chart heights."""
import os
from playwright.sync_api import sync_playwright

html_path = "file:///app/poster_full.html"

with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox"])
    page = browser.new_page(viewport={"width": 1700, "height": 4000})
    page.goto(html_path, wait_until="networkidle", timeout=30000)
    page.wait_for_timeout(4000)

    # Check rendered canvas sizes
    info = page.evaluate("""
    () => {
        const sections = ['inf-intel','inf-speed','inf-price','inf-tradeoff'];
        return sections.map(id => {
            const el = document.getElementById(id);
            if (!el) return { id, error: 'not found' };
            const canvas = el.querySelector('canvas');
            return {
                id,
                el_h: el.clientHeight,
                el_w: el.clientWidth,
                canvas_h: canvas ? canvas.height : 'no canvas',
                canvas_w: canvas ? canvas.width : 'no canvas',
                scrollH: document.body.scrollHeight
            };
        });
    }
    """)
    for item in info:
        print(item)

    browser.close()

