#!/usr/bin/env python3
"""Debug SVG sizes."""
from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox"])
    page = browser.new_page(viewport={"width": 1700, "height": 5000})
    page.goto("file:///app/poster_full.html", wait_until="networkidle", timeout=30000)
    page.wait_for_timeout(5000)

    info = page.evaluate("""
    () => {
        const ids = ['inf-intel','inf-speed','inf-price','inf-tradeoff'];
        return ids.map(id => {
            const el = document.getElementById(id);
            if (!el) return {id, err: 'not found'};
            const svg = el.querySelector('svg');
            const rect = el.getBoundingClientRect();
            return {
                id,
                el_h: rect.height,
                el_scrollH: el.scrollHeight,
                svg_vb: svg ? svg.getAttribute('viewBox') : null,
                svg_dh: svg ? svg.getAttribute('height') : null,
                scrollH: document.body.scrollHeight
            };
        });
    }
    """)
    for item in info: print(item)
    browser.close()

