#!/usr/bin/env python3
"""Render the full poster and save as final PNG."""
import os
from PIL import Image
from playwright.sync_api import sync_playwright

html_path = "file:///app/poster_full.html"
raw_path = "/app/output/poster_raw.png"
out_path = "/app/output/final_poster.png"
POSTER_W = 1684

os.makedirs("/app/output", exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox", "--disable-dev-shm-usage"])
    page = browser.new_page(viewport={"width": 1700, "height": 6000})
    page.goto(html_path, wait_until="networkidle", timeout=30000)
    page.wait_for_timeout(4000)

    page_h = page.evaluate("document.body.scrollHeight")
    print(f"Page: {page.browser.version}, height={page_h}px")

    # Screenshot
    page.screenshot(path=raw_path, full_page=True)
    browser.close()

# ── Crop to content (remove dark margins) ──────────────────────────────────────
raw = Image.open(raw_path).convert("RGBA")
w, h = raw.size
print(f"Raw: {w}×{h}")

px = raw.load()

# Top crop: find first row with significant non-background content
def find_edge(img, axis='y', direction='top'):
    w, h = img.size
    px = img.load()
    if axis == 'y':
        if direction == 'top':
            for y in range(h):
                for x in range(0, w, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return max(0, y - 3)
            return 0
        else:
            for y in range(h - 1, -1, -1):
                for x in range(0, w, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return min(h, y + 3)
            return h
    else:
        if direction == 'left':
            for x in range(w):
                for y in range(0, h, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return max(0, x - 3)
            return 0
        else:
            for x in range(w - 1, -1, -1):
                for y in range(0, h, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return min(w, x + 3)
            return w

top    = find_edge(raw, 'y', 'top')
bottom = find_edge(raw, 'y', 'bottom')
left   = find_edge(raw, 'x', 'left')
right  = find_edge(raw, 'x', 'right')

print(f"Crop: top={top} bottom={bottom} left={left} right={right}")
cropped = raw.crop((left, top, right, bottom))

# Scale to poster width if needed
if cropped.width != POSTER_W:
    ratio = POSTER_W / cropped.width
    new_h = int(cropped.height * ratio)
    cropped = cropped.resize((POSTER_W, new_h), Image.LANCZOS)
    print(f"Scaled to: {POSTER_W}×{new_h}")

# Ensure minimum A1-ish height
min_h = 2384
if cropped.height < min_h:
    # Pad to A1 height
    pad = Image.new("RGBA", (POSTER_W, min_h), (13, 17, 23, 255))
    paste_y = (min_h - cropped.height) // 2
    pad.paste(cropped, (0, paste_y), cropped)
    cropped = pad
    print(f"Padded to A1: {POSTER_W}×{min_h}")

print(f"Final: {cropped.size[0]}×{cropped.size[1]}")
cropped.save(out_path, "PNG")
print(f"✓ Saved: {out_path}")
os.remove(raw_path)

