#!/usr/bin/env python3
"""Final render: capture full poster, crop to content, deliver as PNG."""
import os
from PIL import Image
from playwright.sync_api import sync_playwright

html_path = "file:///app/poster_full.html"
raw_path = "/app/output/poster_raw.png"
out_path = "/app/output/final_poster.png"
POSTER_W = 1684

os.makedirs("/app/output", exist_ok=True)

# ── 1. Render the poster full-page ──────────────────────────────────────────
with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox", "--disable-dev-shm-usage"])
    page = browser.new_page(viewport={"width": 1700, "height": 6000})
    page.goto(html_path, wait_until="networkidle", timeout=30000)
    page.wait_for_timeout(4000)

    # Verify charts rendered
    charts = page.evaluate("""
    () => {
        return ['ii-intel','ii-speed','ii-price','ii-tradeoff'].map(id => {
            const el = document.getElementById(id);
            const svg = el ? el.querySelector('svg') : null;
            return {
                id,
                svg_w: svg ? svg.getAttribute('width') : null,
                svg_h: svg ? svg.getAttribute('height') : null,
                svg_vb: svg ? svg.getAttribute('viewBox') : null
            };
        });
    }
    """)
    for c in charts: print(f"  {c}")

    page.screenshot(path=raw_path, full_page=True)
    print(f"  Screenshot saved ({page.viewport['width']}×{page.viewport['height']})")
    browser.close()

# ── 2. Crop & scale ──────────────────────────────────────────────────────────
raw = Image.open(raw_path).convert("RGBA")
w, h = raw.size
print(f"Raw: {w}×{h}")
px = raw.load()

BG_R, BG_G, BG_B = 20, 20, 30

def is_bg(c):
    return c[0] < BG_R and c[1] < BG_G and c[2] < BG_B

def find_edge(axis, direction, step=5):
    if axis == 'y':
        if direction == 'top':
            for y in range(0, h, step):
                for x in range(0, w, step):
                    if not is_bg(px[x, y]):
                        return max(0, y - 2)
            return 0
        else:
            for y in range(h - 1, -1, -step):
                for x in range(0, w, step):
                    if not is_bg(px[x, y]):
                        return min(h, y + 3)
            return h
    else:
        if direction == 'left':
            for x in range(0, w, step):
                for y in range(0, h, step):
                    if not is_bg(px[x, y]):
                        return max(0, x - 2)
            return 0
        else:
            for x in range(w - 1, -1, -step):
                for y in range(0, h, step):
                    if not is_bg(px[x, y]):
                        return min(w, x + 3)
            return w

top  = find_edge('y', 'top',   step=3)
bot  = find_edge('y', 'bottom', step=3)
left = find_edge('x', 'left',  step=3)
right= find_edge('x', 'right', step=3)

print(f"Crop: top={top} bot={bot} left={left} right={right}")
content_h = bot - top
content_w = right - left

# Scale to POSTER_W width
if content_w != POSTER_W:
    ratio = POSTER_W / content_w
    new_h = int(content_h * ratio)
    cropped = raw.crop((left, top, right, bot))
    final = cropped.resize((POSTER_W, new_h), Image.LANCZOS)
    print(f"Scaled from {content_w}×{content_h} to {POSTER_W}×{new_h}")
else:
    final = raw.crop((left, top, right, bot))

# Pad to A1 minimum if needed
A1_H = 2384
if final.height < A1_H:
    pad = Image.new("RGBA", (POSTER_W, A1_H), (13, 17, 23, 255))
    paste_y = (A1_H - final.height) // 2
    pad.paste(final, (0, paste_y))
    final = pad
    print(f"Padded to {POSTER_W}×{A1_H}")

print(f"Final size: {final.size[0]}×{final.size[1]}")
final.save(out_path, "PNG")
print(f"✓ Saved: {out_path}")
os.remove(raw_path)

