html_path = "file:///app/poster_full.html"
raw_path = "/app/output/poster_raw.png"
out_path = "/app/output/final_poster.png"
POSTER_W = 1684

os.makedirs("/app/output", exist_ok=True)

with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox", "--disable-dev-shm-usage"])
    page = browser.new_page(viewport={"width": 1700, "height": 6000})
    page.goto(html_path, wait_until="networkidle", timeout=30000)
    page.wait_for_timeout(4000)

    page_h = page.evaluate("document.body.scrollHeight")
    print(f"Page height: {page_h}px")

    # Screenshot
    page.screenshot(path=raw_path, full_page=True)
    browser.close()

