def find_edge(img, axis='y', direction='top'):
    w, h = img.size
    px = img.load()
    if axis == 'y':
        if direction == 'top':
            for y in range(h):
                for x in range(0, w, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return max(0, y - 3)
            return 0
        else:
            for y in range(h - 1, -1, -1):
                for x in range(0, w, 5):
                    r, g, b, a = px[x, y]
                    if not (r < 22 and g < 22 and b < 32):
                        return min(h, y + 3)
            return h
    else:
        if direction == 'left':
            for x in range(w):
                for y in range(0, h, 5):
